grid:opt-editable.example:
const grid = new SlickGrid('#grid', data, columns, {
  editable: true,
  autoEdit: false,
});
// give each editable column an `editor`
columns[0].editor = Editors.Text;

grid:m-setColumns.example:
const widths = Object.fromEntries(grid.getColumns().map((c) => [c.id, c.width]));
for (const c of nextColumns) c.width = widths[c.id] ?? c.width;
grid.setColumns(nextColumns);

grid:evt-onSort.example:
grid.onSort.subscribe((e, args) => {
  const cols = args.sortCols ?? [{ sortCol: args.sortCol, sortAsc: args.sortAsc }];
  dataView.sort((a, b) => {
    for (const { sortCol, sortAsc } of cols) {
      const dir = sortAsc ? 1 : -1;
      const x = a[sortCol.field], y = b[sortCol.field];
      if (x !== y) return (x > y ? 1 : -1) * dir;
    }
    return 0;
  });
});

dataview:m-endUpdate.example:
dataView.beginUpdate();
for (const row of incoming) dataView.updateItem(row.id, row);
dataView.endUpdate();

